@@ -0,0 +1,341 @@
+/*
+  원이 놓이는 칸이다. 이 칸의 폭이 곧 옆 카드의 폭을 정한다. 숨은 동안(0)은 초승달이 설 만큼만 두어 카드가
+  넓게 서고, 1이면 절반쯤, 2면 끝까지 원과 같은 속도로 넓어져 카드가 함께 줄어든다. 숨을 때는 거꾸로 칸이
+  줄며 카드 끝이 오른쪽으로 늘어나, 그 끝에 걸친 원이 오른쪽으로 밀려가며 흐려진다.
+
+  왼쪽으로 18px 물러서 카드 테두리에 걸친다. 카드 안쪽 여백 정도라 카드 내용을 가리지 않는다. 격자 자리와
+  위아래 여백은 쓰는 화면이 정한다.
+
+  칸 자체는 포인터를 받지 않는다. 칸은 원을 두르는 네모라, 받으면 보이지 않는 칸 모서리가 옆 카드 끝의 클릭을
+  가로챈다. 다 드러난 원만 받는다(아래 .orb).
+*/
+.dock {
+  --orb-size: 150px;
+  /* 원의 드러남·모양·색과 칸 폭 변화가 모두 이 시간과 곡선을 쓴다. */
+  --orb-motion: 620ms cubic-bezier(0.22, 1, 0.36, 1);
+
+  position: relative;
+  z-index: 1;
+  display: flex;
+  flex-direction: column;
+  align-self: start;
+  pointer-events: none;
+  align-items: flex-start;
+  width: 60px;
+  margin-left: -18px;
+  transition: width var(--orb-motion);
+}
+
+.dock[data-stage='1'] {
+  width: 96px;
+}
+
+.dock[data-stage='2'] {
+  width: calc(var(--orb-size) - 18px);
+}
+
+/*
+  채움 색을 등록한다. 등록하지 않은 사용자 정의 속성은 바뀔 때 뚝 끊기는데, 등록한 색은 모양·드러남과 같은
+  속도로 옮겨 간다.
+*/
+@property --thorp-orb-fill {
+  syntax: '<color>';
+  inherits: false;
+  initial-value: #2a2e2d;
+}
+
+/*
+  단추. 모양은 원이라 누를 수 있는 자리도 원이고(모서리를 눌러도 반응하지 않는다), 초점 테두리도 원을 따라
+  그려진다. 보이는 원은 안쪽 장식 요소(.fill)가 그린다.
+
+  넘어갈 수 없는 동안(0~1)은 눌러도 아무 일이 없으므로 칸을 따라 포인터를 받지 않는다. 원이 카드 모서리에 걸쳐
+  있어, 받으면 흐려져 보이지도 않는 원이 카드 모서리 클릭을 가로챈다. 키보드 초점은 그대로 받는다.
+*/
+.orb {
+  position: relative;
+  display: flex;
+  flex: none;
+  flex-direction: column;
+  align-items: flex-start;
+  justify-content: center;
+  gap: 2px;
+  width: var(--orb-size);
+  height: var(--orb-size);
+  padding: 0 0 0 26px;
+  border: 0;
+  border-radius: 50%;
+  background: transparent;
+  color: var(--thorp-action-foreground);
+  font: inherit;
+  text-align: left;
+  cursor: pointer;
+  isolation: isolate;
+  transition:
+    color var(--orb-motion),
+    transform 240ms cubic-bezier(0.22, 1, 0.36, 1),
+    filter 0.14s ease;
+}
+
+.orb[data-stage='2'] {
+  pointer-events: auto;
+}
+
+.orb[aria-busy='true'] {
+  cursor: progress;
+}
+
+.orb:focus-visible {
+  outline: var(--thorp-focus-outline-compact, var(--thorp-focus-outline));
+  outline-offset: 4px;
+}
+
+/*
+  보이는 원. 단계를 오간다.
+
+  넘어갈 수 없는 동안(0~1)은 원의 앞쪽만 카드 테두리 위에 남는다. 원을 칼로 자르지 않고, 흐림 가림막을
+  왼쪽으로 당겨 앞쪽은 선명하고 뒤쪽은 배경에 스며드는 초승달로 둔다.
+
+  2가 되면 가림막이 오른쪽으로 쓸려 나가며 몸체가 배경에서 떠오른다. 같은 시간 동안 원은 앞으로 기운 물방울
+  모양이 되고 색이 채워진다. 다 떠오르면 흐림은 남지 않는다. 가림막의 흐린 구간이 원 폭 밖으로 완전히
+  빠져나가기 때문이다. 글자는 몸체가 거의 드러난 뒤에 따라 나온다.
+
+  가림막은 원 폭의 두 배 길이다. 앞 절반은 불투명, 그다음 원 폭의 30%에 걸쳐 투명해진다. 가림막을 얼마나
+  당기느냐(`mask-position`)만 바꾸므로 흐린 구간의 모양이 유지된 채 부드럽게 움직인다.
+*/
+.fill {
+  --thorp-orb-fill: var(--thorp-accent);
+
+  position: absolute;
+  z-index: -1;
+  inset: 0;
+  border: 1.5px solid color-mix(in srgb, var(--thorp-accent) 70%, #000);
+  border-radius: 44% 56% 56% 44% / 50% 50% 50% 50%;
+  background: var(--thorp-orb-fill);
+  box-shadow: none;
+  pointer-events: none;
+  -webkit-mask-image: linear-gradient(90deg, #000 50%, transparent 65%);
+  mask-image: linear-gradient(90deg, #000 50%, transparent 65%);
+  -webkit-mask-size: calc(var(--orb-size) * 2) 100%;
+  mask-size: calc(var(--orb-size) * 2) 100%;
+  -webkit-mask-repeat: no-repeat;
+  mask-repeat: no-repeat;
+  -webkit-mask-position: 0 0;
+  mask-position: 0 0;
+  transition:
+    -webkit-mask-position var(--orb-motion),
+    mask-position var(--orb-motion),
+    border-color var(--orb-motion),
+    box-shadow var(--orb-motion),
+    --thorp-orb-fill var(--orb-motion);
+}
+
+/*
+  숨은 단계의 빛 번짐이다. 왼쪽 위에 옅게 번진 빛이 평평한 조각을 둥근 면으로 보이게 한다. 다 드러나면
+  모양·색과 같은 속도로 사라져 단색 채움만 남는다.
+*/
+.fill::before {
+  position: absolute;
+  inset: 0;
+  border-radius: inherit;
+  background: radial-gradient(
+    circle at 26% 30%,
+    color-mix(in oklab, color-mix(in oklab, var(--thorp-accent) 45%, #fff) 16%, transparent) 0%,
+    transparent 58%
+  );
+  opacity: 0;
+  content: '';
+  transition: opacity var(--orb-motion);
+}
+
+.orb[data-stage='0'] .fill::before {
+  opacity: 0.55;
+}
+
+.orb[data-stage='1'] .fill::before {
+  opacity: 1;
+}
+
+.orb > :not(.fill) {
+  position: relative;
+  transition:
+    opacity 300ms ease 260ms,
+    transform var(--orb-motion);
+}
+
+.step {
+  font-size: var(--thorp-text-caption, 0.7rem);
+  font-weight: 700;
+  letter-spacing: 0.08em;
+  opacity: 0.8;
+}
+
+.label {
+  font-size: 1.02rem;
+  font-weight: 800;
+  letter-spacing: -0.02em;
+  white-space: nowrap;
+}
+
+.arrow {
+  margin-top: 6px;
+}
+
+.orb:hover:not(:disabled):not([aria-disabled='true']) {
+  filter: brightness(1.06);
+  transform: translateX(6px);
+}
+
+.orb:hover:not(:disabled):not([aria-disabled='true']) .arrow {
+  transform: translateX(6px);
+}
+
+/*
+  아직 넘어갈 수 없다(0~1). 글자는 보이지 않고 눌리지 않는다. `disabled`든 `aria-disabled`든 같은 모양이다.
+  다 드러난 뒤 잠깐 눌리지 않는 때(요청을 보내는 중)는 조건이 빠진 것이 아니므로 글자를 그대로 둔다.
+
+  세 단계는 **한 색상 계열**에서 밝기와 채도만 오른다: 카드 면에 가까운 깊은 에메랄드(0) → 중간 톤의 초록(1)
+  → 브랜드 초록(2). 불이 점점 켜지는 흐름으로 읽히게 하려는 것이다. 회색이나 다른 색을 끼우면 초록 단추의 앞
+  단계가 아니라 다른 물건으로 보이고, sRGB에서 회색과 초록을 섞으면 탁한 올리브가 된다. 그래서 oklab에서
+  섞는다. 등록한 색의 전환도 같은 공간에서 보간된다.
+
+  윤곽선 대신 앞쪽(왼쪽) 가장자리에 가는 빛선을 둔다. 두꺼운 테두리는 숨어 있는 조각을 도리어 도드라지게
+  한다. 테두리는 색만 투명하게 두어 두께가 바뀌며 모양이 튀지 않게 한다. 흐림은 뒤쪽 짧은 구간에만 남겨
+  앞쪽은 또렷하다.
+
+  1은 모든 것이 절반쯤 나아간 상태다. 가림막이 반쯤 걷혀 몸체가 밀려 나오고, 모양도 원과 물방울 사이다.
+*/
+.orb:disabled,
+.orb[aria-disabled='true']:not([data-stage='2']) {
+  color: transparent;
+  cursor: default;
+}
+
+.orb:disabled .fill,
+.orb[aria-disabled='true']:not([data-stage='2']) .fill {
+  border-color: transparent;
+}
+
+.orb[data-stage='0'] .fill {
+  --thorp-orb-fill: color-mix(in oklab, var(--thorp-accent) 28%, var(--thorp-surface-raised, #1f2321));
+
+  border-radius: 50%;
+  box-shadow: inset 1.5px 0 0 color-mix(in oklab, var(--thorp-accent) 42%, transparent);
+  -webkit-mask-position: calc(var(--orb-size) * -0.76) 0;
+  mask-position: calc(var(--orb-size) * -0.76) 0;
+}
+
+.orb[data-stage='1'] .fill {
+  --thorp-orb-fill: color-mix(in oklab, var(--thorp-accent) 58%, var(--thorp-surface-raised, #1f2321));
+
+  border-radius: 47% 53% 53% 47% / 50% 50% 50% 50%;
+  box-shadow: inset 2px 0 0 color-mix(in oklab, var(--thorp-accent) 70%, #fff 10%);
+  -webkit-mask-position: calc(var(--orb-size) * -0.42) 0;
+  mask-position: calc(var(--orb-size) * -0.42) 0;
+}
+
+.orb:disabled > .step,
+.orb:disabled > .label,
+.orb:disabled > .arrow,
+.orb[aria-disabled='true']:not([data-stage='2']) > .step,
+.orb[aria-disabled='true']:not([data-stage='2']) > .label,
+.orb[aria-disabled='true']:not([data-stage='2']) > .arrow {
+  opacity: 0;
+  transform: translateX(-12px);
+  transition-delay: 0s;
+}
+
+/*
+  모양은 곧게 바뀌지 않고 한 번 일렁인다. 떠오를 때는 가로로 늘었다가 반대로 기운 뒤 물방울로 자리 잡는다.
+  숨을 때는 오른쪽으로 밀려 나가며 한 번 출렁이고 원으로 돌아가 초승달 속으로 들어간다. 1로 오갈 때는 작게
+  한 번 밀려 나오듯 출렁인다. 단계가 바뀌면 애니메이션 이름이 바뀌어 처음부터 다시 돈다. 끝 모양은 각
+  단계의 정지 모양과 같아 멈출 때 튀지 않는다.
+*/
+.orb[data-stage='2'] .fill {
+  animation: orb-emerge var(--orb-motion);
+}
+
+.orb[data-stage='1'] .fill {
+  animation: orb-nudge var(--orb-motion);
+}
+
+.orb[data-stage='0'] .fill {
+  animation: orb-recede var(--orb-motion);
+}
+
+@keyframes orb-nudge {
+  0% {
+    border-radius: 50%;
+    transform: none;
+  }
+
+  45% {
+    border-radius: 56% 44% 48% 52% / 46% 54% 46% 54%;
+    transform: translateX(8px) scale(1.04, 0.97);
+  }
+
+  100% {
+    border-radius: 47% 53% 53% 47% / 50% 50% 50% 50%;
+    transform: none;
+  }
+}
+
+@keyframes orb-emerge {
+  0% {
+    border-radius: 50%;
+    transform: scale(0.92);
+  }
+
+  38% {
+    border-radius: 60% 40% 46% 54% / 44% 58% 42% 56%;
+    transform: scale(1.07, 0.94);
+  }
+
+  68% {
+    border-radius: 38% 62% 60% 40% / 56% 44% 56% 44%;
+    transform: scale(0.98, 1.03);
+  }
+
+  100% {
+    border-radius: 44% 56% 56% 44% / 50% 50% 50% 50%;
+    transform: none;
+  }
+}
+
+@keyframes orb-recede {
+  0% {
+    border-radius: 44% 56% 56% 44% / 50% 50% 50% 50%;
+    transform: none;
+  }
+
+  40% {
+    border-radius: 36% 64% 58% 42% / 58% 42% 58% 42%;
+    transform: translateX(18px) scale(1.05, 0.95);
+  }
+
+  75% {
+    border-radius: 54% 46% 48% 52% / 46% 54% 46% 54%;
+    transform: translateX(8px) scale(0.97, 1.02);
+  }
+
+  100% {
+    border-radius: 50%;
+    transform: none;
+  }
+}
+
+/* 움직임 줄이기: 칸도 원도 움직이지 않고 단계의 정지 모양으로 바로 바뀐다. */
+@media (prefers-reduced-motion: reduce) {
+  .dock,
+  .orb,
+  .fill,
+  .fill::before,
+  .orb > :not(.fill) {
+    transition: none;
+    animation: none;
+  }
+
+  .orb:hover:not(:disabled):not([aria-disabled='true']),
+  .orb:hover:not(:disabled):not([aria-disabled='true']) .arrow {
+    transform: none;
+  }
+}

