+.group {
+  display: grid;
+  align-content: start;
+  gap: 6px;
+  min-width: 0;
+}
+
+.groupHead {
+  display: flex;
+  flex-wrap: wrap;
+  align-items: center;
+  justify-content: space-between;
+  gap: 6px 12px;
+  min-height: 30px;
+}
+
+.groupTitle {
+  margin: 0;
+  color: var(--thorp-muted);
+  font-size: var(--thorp-text-caption, 0.72rem);
+  font-weight: 700;
+  letter-spacing: 0.04em;
+}
+
+/* '모두 기본값 복원' 뒤에 초점을 받는 자리다. 누른 단추가 사라지므로 묶음 제목이 초점을 이어받는다. */
+.groupTitle:focus {
+  outline: none;
+}
+
+.groupTitle:focus-visible {
+  border-radius: 4px;
+  outline: var(--thorp-focus-outline-compact, var(--thorp-focus-outline));
+  outline-offset: 2px;
+}
+
+.rows {
+  display: grid;
+  border-top: 1px solid var(--thorp-line);
+}
+
+/* 행 하나. 이름은 왼쪽, 값과 조작은 오른쪽 끝이다. */
+.row {
+  border-bottom: 1px solid var(--thorp-line);
+}
+
+/* 되돌린 뒤 초점을 받을 조작이 없을 때만 행 자신이 초점을 받는다. */
+.row:focus-visible {
+  outline: var(--thorp-focus-outline-compact, var(--thorp-focus-outline));
+  outline-offset: 2px;
+}
+
+.head {
+  display: flex;
+  flex-wrap: wrap;
+  align-items: center;
+  gap: 6px 12px;
+  min-height: 48px;
+  padding: 6px 0;
+}
+
+.labelGroup {
+  display: inline-flex;
+  flex: 0 1 auto;
+  align-items: center;
+  gap: 2px;
+  min-width: 0;
+  color: var(--thorp-copy);
+  font-size: var(--thorp-text-small, 0.82rem);
+  font-weight: 600;
+  white-space: nowrap;
+}
+
+.unit {
+  margin-left: 4px;
+  color: var(--thorp-muted);
